local function Anim(Cine, Timp, Detalii)
game.TweenService:Create(Cine, TweenInfo.new(Timp), Detalii):Play()
end

local function Rotund(Cine, Raza)
local _ = Instance.new("UICorner")
_.CornerRadius = UDim.new(0, Raza or 5)
_.Parent = Cine
end

local function Margine(Cine, Grosime, Transparenta, Culoare)
local _ = Instance.new("UIStroke")
_.ApplyStrokeMode = 1 -- Border
_.Thickness = Grosime or 1
_.Transparency = Transparenta or 0
_.Color = Color3.fromHex(Culoare or "9430FF")
_.Parent = Cine
return _
end

local function Aleatoriu()
local _ = ""
for i = 1, math.random(20, 200) do
_ ..= utf8.char(math.random(20, 40000))
end
return _
end

local function Fisier(Nume, Continut)
if Continut and not isfile(Nume) then
writefile(Nume, Continut)
end

if not Continut and not isfolder(Nume) then
makefolder(Nume)
end
end

local function JsonDecode(_)
return game:GetService("HttpService"):JSONDecode(_)
end


