task.wait(4)
Cutie.PlaceholderText = "insert key (leave empty if none was given)"
Cutie.PlaceholderColor3 = Color3.fromHex("B0B0B0")
Anim(Cutie.UIStroke, 0.4, {Color = Color3.fromHex("404040")})
return
end
VL_Key = _
writefile("Vonalia/" .. VL_Name .. "/Key.txt", _)
end)

Copiaza.MouseButton1Click:Connect(function()
if not pcall(function()
Clipboard("https://beta.vonalia.com/Whitelist?Username=" .. VL_Name .. "&Hardware=" .. VL_Hardware)
end) then Clipboard("Failed to Copy. Username or Hardware is missing") end
Anim(Copiaza, 0.4, {TextColor3 = Color3.fromHex("FFFFFF")})
Anim(Copiaza, 0.4, {BackgroundColor3 = Color3.fromHex("000000")})
task.wait(0.4)
Anim(Copiaza, 0.4, {TextColor3 = Color3.fromHex("000000")})
Anim(Copiaza, 0.4, {BackgroundColor3 = Color3.fromHex("FFFFFF")})
end)

Valideaza.MouseButton1Click:Connect(PreValideaza)

Anim(Fundal, 0.4, {Size = UDim2.new(0, 400, 0, 300)})
task.wait(0.4)

local _ = readfile("Vonalia/" .. VL_Name .. "/Key.txt")

if #_ ~= 132 or not _:match("^KEY_[a-f0-9]+$") then
writefile("Vonalia/" .. VL_Name .. "/Key.txt", "")
end

PreValideaza()

while not Valid do task.wait(1) end
